export default {"file":"librarian-attendance.html","title":"Librarian Attendance - Schoolix","htmlClass":"","bodyClass":"library-dashboard-app","body":"\r\n<div id=\"sxPageLoader\" class=\"sx-page-loader\" role=\"status\" aria-live=\"polite\">\r\n  <section class=\"dots-container\" aria-label=\"Loading page\">\r\n    <div class=\"dot\"></div><div class=\"dot\"></div><div class=\"dot\"></div><div class=\"dot\"></div><div class=\"dot\"></div>\r\n  </section>\r\n</div>\r\n<div class=\"library-app-layout\">\r\n  <div class=\"library-sidebar-overlay\" id=\"librarySidebarOverlay\" aria-hidden=\"true\"></div>\r\n  <aside class=\"library-sidebar\" id=\"librarySidebar\"></aside>\r\n  <main class=\"library-main\">\r\n    <header class=\"library-page-topbar\">\r\n      <div>\r\n        <h1 class=\"library-page-title\">My Attendance</h1>\r\n        <div class=\"library-page-meta\">Daily attendance marked through QR or by admin.</div>\r\n      </div>\r\n      <button class=\"library-menu-button\" id=\"libraryMenuButton\" type=\"button\" aria-label=\"Open library navigation\" aria-expanded=\"false\">\r\n        <svg viewBox=\"0 0 24 24\"><path d=\"M4 6h16\"></path><path d=\"M4 12h16\"></path><path d=\"M4 18h16\"></path></svg>\r\n      </button>\r\n    </header>\r\n    <section class=\"library-card\">\r\n      <div id=\"libraryAttendanceMount\"></div>\r\n    </section>\r\n  </main>\r\n</div>\r\n<script src=\"library-portal.js\"></script>\r\n<script type=\"module\" src=\"staff-qr-checkin.js\"></script>\r\n<script type=\"module\" src=\"access-control.js\"></script>\r\n<script src=\"schoolix-polish.js\" defer></script>\r\n","styles":[{"tag":"link","attributes":{"rel":"stylesheet","href":"schoolix-polish.css"},"text":""},{"tag":"link","attributes":{"rel":"stylesheet","href":"library-portal.css"},"text":""}],"scripts":[{"attributes":{"id":"sxCriticalLoaderScript"},"text":"\r\n(function () {\r\n  var root = document.documentElement;\r\n  root.classList.add(\"sx-page-loading\");\r\n  window.SchoolixPageLoaderEarly = window.SchoolixPageLoaderEarly || { startedAt: Date.now() };\r\n\r\n  function markEarlyReady(reason) {\r\n    window.SchoolixPageLoaderEarly.ready = true;\r\n    window.SchoolixPageLoaderEarly.reason = reason || \"dom-ready\";\r\n    try {\r\n      window.dispatchEvent(new CustomEvent(\"schoolix:critical-load-ready\", { detail: window.SchoolixPageLoaderEarly }));\r\n    } catch (_) {}\r\n  }\r\n\r\n  function afterFirstPaint(reason) {\r\n    requestAnimationFrame(function () {\r\n      requestAnimationFrame(function () { markEarlyReady(reason); });\r\n    });\r\n  }\r\n\r\n  function emergencyHide() {\r\n    if (window.SchoolixPageLoader || !root.classList.contains(\"sx-page-loading\")) return;\r\n    root.classList.remove(\"sx-page-loading\");\r\n    root.classList.add(\"sx-page-loaded\");\r\n    var loader = document.getElementById(\"sxPageLoader\");\r\n    if (!loader) return;\r\n    loader.classList.add(\"is-hidden\");\r\n    setTimeout(function () { loader.remove(); }, 260);\r\n  }\r\n\r\n  if (document.readyState === \"loading\") {\r\n    document.addEventListener(\"DOMContentLoaded\", function () { afterFirstPaint(\"dom-ready\"); }, { once: true });\r\n  } else {\r\n    afterFirstPaint(document.readyState === \"complete\" ? \"document-complete\" : \"dom-ready\");\r\n  }\r\n  window.addEventListener(\"load\", function () { markEarlyReady(\"window-load\"); }, { once: true });\r\n  setTimeout(emergencyHide, 3200);\r\n}());\r\n"},{"attributes":{"src":"library-portal.js"},"text":""},{"attributes":{"type":"module","src":"staff-qr-checkin.js"},"text":""},{"attributes":{"type":"module","src":"access-control.js"},"text":""},{"attributes":{"src":"schoolix-polish.js"},"text":""}]};
